    delete process.env['TUNGO_WEBHOOK_SECRET'];
    const bare = new Tungo({ apiKey: API_KEY });
    process.env['TUNGO_WEBHOOK_SECRET'] = valid.secret;
    const fromEnv = new Tungo({ apiKey: API_KEY });
