    assert.ok(tampered instanceof WebhookVerificationError);
    assert.equal(tampered.reason, 'signature_mismatch');
    const stale = await rejection(client.verifyWebhook(valid.body, valid.headers, { now: valid.now + 301 }));
    assert.ok(stale instanceof WebhookVerificationError);
    assert.equal(stale.reason, 'timestamp_too_old');
